101	    private static void insert(int[] values, int fromIndex, int index) {
102	        int value = values[index];
103	        int position = index - 1;
104	
105	        while (position >= fromIndex && values[position] > value) {
106	            values[position + 1] = values[position];
107	            position--;
108	        }
109	
110	        values[position + 1] = value;
111	    }
