179	    private static boolean isSorted(Range range, OutOfOrderPredicate outOfOrderPredicate) {
180	        for (int index = range.fromIndex + 1; index < range.toIndex; index++) {
181	            if (outOfOrderPredicate.test(index - 1, index)) {
182	                return false;
183	            }
184	        }
185	
186	        return true;
187	    }
