189	    private static final class Range {
190	        private final int fromIndex;
191	        private final int toIndex;
192	
193	        private Range(int fromIndex, int toIndex) {
194	            this.fromIndex = fromIndex;
195	            this.toIndex = toIndex;
196	        }
197	
198	        private static Range full(int length) {
199	            return new Range(0, length);
200	        }
201	
202	        private static Range of(int length, int fromIndex, int toIndex) {
203	            if (fromIndex < 0 || toIndex > length || fromIndex > toIndex) {
204	                throw new IndexOutOfBoundsException(
205	                        "Invalid range [" + fromIndex + ", " + toIndex + ") for length " + length);
206	            }
207	
208	            return new Range(fromIndex, toIndex);
209	        }
210	
211	        private boolean isTrivial() {
212	            return toIndex - fromIndex < 2;
213	        }
214	    }
